import {uuid,validUUID,normalize} from './core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let device=null,server=null,characteristics=[],records=[],subscribed=new Set(),busy=false;
const get=id=>document.getElementById(id);
function status(text){if(get('transport-status'))get('transport-status').textContent=text;}
function capture(characteristic,value,direction){
  if(records.length>=10000){status('10,000-event limit reached. Disconnect and save.');disconnect();return;}
  try{records.push(normalize({timestamp:new Date().toISOString(),action:get('live-action')?.value.trim()||'Browser exploration',direction,service:characteristic.service.uuid,characteristic:characteristic.uuid,value:[...new Uint8Array(value.buffer,value.byteOffset,value.byteLength)],source:'Web Bluetooth • own GATT session'}));status(`${records.length} events recorded locally. Save the session before leaving.`);}catch(e){status(e.message);}
}
function redraw(){if(!get('transport-characteristics'))return;get('connect-browser').disabled=!navigator.bluetooth||!isSecureContext||busy||Boolean(server?.connected);get('disconnect-browser').disabled=!server?.connected;get('save-browser').disabled=!records.length;
  get('transport-characteristics').innerHTML=characteristics.map((c,i)=>`<div class="command"><strong>${esc(c.uuid)}</strong><p class="muted">Service ${esc(c.service.uuid)} · ${['read','write','writeWithoutResponse','notify','indicate'].filter(p=>c.properties[p]).join(', ')||'No exposed properties'}</p><div class="actions"><button data-read="${i}" ${!c.properties.read?'disabled':''}>Read value</button><button data-notify="${i}" ${!(c.properties.notify||c.properties.indicate)?'disabled':''}>${subscribed.has(c)?'Stop notifications':'Record notifications'}</button></div></div>`).join('');
  document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const c=characteristics[Number(b.dataset.read)];capture(c,await c.readValue(),'read');}catch(e){status(`Read failed: ${e.message}`);}finally{redraw();}});
  document.querySelectorAll('[data-notify]').forEach(b=>b.onclick=async()=>{b.disabled=true;const c=characteristics[Number(b.dataset.notify)];try{if(subscribed.has(c)){await c.stopNotifications();subscribed.delete(c);}else{await c.startNotifications();subscribed.add(c);}status(`${subscribed.size} notification subscriptions active. These belong to this browser’s connection.`);}catch(e){status(`Notification subscription failed: ${e.message}`);}finally{redraw();}});
}
function disconnect(){device?.gatt?.disconnect();server=null;subscribed.clear();status(`Disconnected. ${records.length} captured events remain in memory until saved.`);redraw();}
function mount(){if(!get('capture-input')||get('transport-panel'))return;
  const panel=document.createElement('section');panel.id='transport-panel';panel.className='card';panel.innerHTML=`<details><summary>Connect from this tablet / desktop</summary><p>Use this browser’s Bluetooth radio to explore your own BLE device. This is a separate GATT connection, not a vendor-app sniffer. Close the vendor app if the device only permits one connection.</p><p class="notice">Web Bluetooth: ${navigator.bluetooth&&isSecureContext?'API detected; permissions and operating-system support still required':'unavailable here; use a supported browser over HTTPS or import a capture'}. Home Assistant proxies are reached by the installed integration, not by Web Bluetooth.</p><div class="fields"><label>Permitted service UUIDs<input id="browser-services" placeholder="fff0, 180f"></label><label>Current action label<input id="live-action" value="Browser exploration"></label></div><p class="muted">Supply service UUIDs from the device documentation or a GATT discovery. Browser permissions require permitted services up front; unknown services are not universally enumerable.</p><div class="actions"><button id="connect-browser" ${!navigator.bluetooth||!isSecureContext?'disabled':''}>Choose device & explore</button><button id="disconnect-browser" disabled>Disconnect</button><button id="save-browser" disabled>Save captured session</button></div><p id="transport-status" class="muted" role="status">No browser device connected.</p><div id="transport-characteristics"></div><details><summary>USB / Web Serial flexibility</summary><p class="muted">A generic USB Bluetooth adapter is not a serial sniffer. USB-host support, browser APIs and a specific adapter/firmware protocol are required. No USB adapter driver is implemented in this release. Desktop Web Serial support does not guarantee Android support. An OS-level companion or WebUSB-compatible hardware can be added once a concrete adapter is selected.</p><a href="https://developer.chrome.com/docs/capabilities/serial" target="_blank" rel="noreferrer">Web Serial requirements ↗</a></details></details>`;
  get('content').prepend(panel);
  get('connect-browser').onclick=async()=>{if(busy)return;try{const services=get('browser-services').value.split(/[,\s]+/).filter(Boolean).map(uuid);if(!services.length||services.some(s=>!validUUID(s)))throw Error('Enter valid service UUIDs before opening the chooser.');if(records.length&&!confirm('Start a new capture? Unsaved browser events will be discarded.'))return;busy=true;redraw();device=await navigator.bluetooth.requestDevice({acceptAllDevices:true,optionalServices:services});records=[];characteristics=[];server=await device.gatt.connect();device.addEventListener('gattserverdisconnected',()=>{server=null;subscribed.clear();status('Device disconnected. Save any captured events.');redraw();},{once:true});for(const s of await server.getPrimaryServices()){for(const c of await s.getCharacteristics()){c.addEventListener('characteristicvaluechanged',event=>{if(subscribed.has(c)){capture(c,event.target.value,c.properties.notify?'notify':'indicate');if(get('save-browser'))get('save-browser').disabled=false;}});characteristics.push(c);}}status(`Connected to ${device.name||'selected device'}. ${characteristics.length} accessible characteristics. No command writes are available.`);}catch(e){status(`Connection failed or cancelled: ${e.message}`);device?.gatt?.disconnect();server=null;}finally{busy=false;redraw();}};
  get('disconnect-browser').onclick=disconnect;
  get('save-browser').onclick=()=>{if(!records.length)return;const observations=structuredClone(records);disconnect();records=[];window.dispatchEvent(new CustomEvent('ble-browser-capture',{detail:{observations,name:`Browser • ${device?.name||'BLE device'}`}}));};redraw();
}
new MutationObserver(mount).observe(document.getElementById('content'),{childList:true});mount();
window.addEventListener('beforeunload',e=>{if(records.length){e.preventDefault();e.returnValue='';}});
